<script setup lang="ts">
import { useCmsI18n } from '@/composables/useCmsI18n';
import { onMounted, ref } from 'vue';
import { cmsApi } from '../api';
import type { Scope, Category, FormData, FormOption } from '../types';
import { useOperation } from './useOperation';
const { t } = useCmsI18n();
const props = defineProps<{scope: Scope; can: (permission:string)=>boolean}>();
const { busy,error,run } = useOperation(); const rows = ref<Category[]>([]), dialog = ref(false), form = ref<FormData>({}), formOptions = ref<FormOption[]>([]);
async function load() { if (!(props.can('cms:category:list'))) return; await run(async()=>{const result=await cmsApi.categoriesWithForms(props.scope);rows.value=result.categories;formOptions.value=result.forms||[];}); }
function open(row?:Category) { if (!(props.can(row ? 'cms:category:edit' : 'cms:category:create'))) return; form.value=row?{...row,desired_path:row.url}:{name:'',description:'',desired_path:'',parent_id:'',list_template:'category',detail_template:'detail',form_code:'',status:1,locale_status:1};dialog.value=true; }
async function save() { if (!(props.can(form.value.id ? 'cms:category:edit' : 'cms:category:create'))) return; await run(async()=>{await cmsApi.saveCategory({...form.value,...props.scope});dialog.value=false;await load();}); }
async function toggle(row:Category,field:string,value:unknown){if(!props.can('cms:category:status'))return;await run(async()=>{await cmsApi.categoryStatus({...props.scope,id:row.id,[field]:value?1:0});await load();});}
onMounted(load);
</script>
<template><div><el-alert v-if="error" :title="error" type="error" :closable="false" /><div class="toolbar"><el-button v-if="can('cms:category:create')" type="primary" @click="open()">{{ t('cms.labels.newCategory') }}</el-button></div><el-table :data="rows" v-loading="busy"><el-table-column prop="id" :label="t('cms.labels.categoryId')" width="100" /><el-table-column prop="name" :label="t('cms.labels.categoryName')" /><el-table-column prop="url" :label="t('cms.labels.urlPath')" /><el-table-column :label="t('cms.labels.globallyEnabled')"><template #default="{row}"><el-switch :model-value="!!Number(row.status)" :disabled="busy||!can('cms:category:status')" @change="toggle(row as Category,'status',$event)" /></template></el-table-column><el-table-column :label="t('cms.labels.enabledForThisLanguage')"><template #default="{row}"><span v-if="row.translated===false">{{ t('cms.labels.translationPending') }}</span><el-switch v-else :model-value="!!Number(row.locale_status)" :disabled="busy||!can('cms:category:status')" @change="toggle(row as Category,'locale_status',$event)" /></template></el-table-column><el-table-column :label="t('cms.labels.actions')"><template #default="{row}"><el-button v-if="can('cms:category:edit')" link @click="open(row as Category)">{{ t('cms.labels.edit') }}</el-button></template></el-table-column></el-table>
<el-dialog v-model="dialog" :title="t('cms.labels.categorySettings')" width="min(680px, 94vw)" :close-on-click-modal="false"><el-alert v-if="error" :title="error" type="error" :closable="false" /><el-form label-position="top"><el-form-item :label="t('cms.labels.categoryName')" required><el-input v-model="form.name" /></el-form-item><el-form-item :label="t('cms.labels.parentCategory')"><el-select v-model="form.parent_id" clearable><el-option v-for="row in rows.filter(item=>item.id !== form.id)" :key="row.id" :label="row.name" :value="row.id" /></el-select></el-form-item><el-form-item :label="t('cms.labels.urlPath')" required><el-input v-model="form.desired_path" placeholder="/news/" /></el-form-item><el-form-item :label="t('cms.labels.categoryDescription')"><el-input v-model="form.description" type="textarea" /></el-form-item><el-form-item :label="t('cms.labels.seoTitle')"><el-input v-model="form.seo_title" /></el-form-item><el-form-item :label="t('cms.labels.seoDescription')"><el-input v-model="form.seo_description" type="textarea" /></el-form-item><el-form-item :label="t('cms.labels.listTemplate')"><el-input v-model="form.list_template" /></el-form-item><el-form-item :label="t('cms.labels.detailTemplate')"><el-input v-model="form.detail_template" /></el-form-item><el-form-item :label="t('cms.labels.attachedForm')"><el-select v-model="form.form_code" clearable :placeholder="t('cms.labels.noAttachedForm')" @clear="form.form_code=''"><el-option :label="t('cms.labels.noAttachedForm')" value="" /><el-option v-for="item in formOptions" :key="item.code" :label="item.status ? item.name : t('cms.labels.disabledFormOption', {name: item.name})" :value="item.code" /></el-select><small class="muted">{{ t('cms.labels.attachedCategoryFormHelp') }}</small></el-form-item><el-form-item :label="t('cms.labels.sortOrder')"><el-input-number v-model="form.sort_order" :min="0" /></el-form-item><el-form-item :label="t('cms.labels.enabledForThisLanguage')"><el-switch v-model="form.locale_status" :disabled="!can('cms:category:status')" :active-value="1" :inactive-value="0" /></el-form-item><el-form-item :label="t('cms.labels.globallyEnabledForAllLanguages')"><el-switch v-model="form.status" :disabled="!can('cms:category:status')" :active-value="1" :inactive-value="0" /></el-form-item></el-form><template #footer><el-button @click="dialog=false">{{ t('cms.labels.cancel') }}</el-button><el-button v-if="can(form.id ? 'cms:category:edit' : 'cms:category:create')" type="primary" :loading="busy" @click="save">{{ t('cms.labels.save') }}</el-button></template></el-dialog></div></template>
<style scoped>.toolbar{margin:16px 0}.muted{display:block;width:100%;margin-top:6px;color:var(--el-text-color-secondary);font-size:12px}</style>
